{
  "$schema": "../../spec/contract.schema.json",
  "capability": "shop.get_order",
  "version": 1,
  "kind": "action",
  "effects": "none",
  "summary": "Read what shipping needs about one order. Returns references and decision fields only.",
  "input": {
    "type": "object",
    "properties": {
      "order_ref": {
        "type": "string",
        "minLength": 1,
        "maxLength": 200,
        "description": "Reference to the order in its source system."
      }
    },
    "required": [
      "order_ref"
    ],
    "additionalProperties": false
  },
  "outcomes": {
    "found": {
      "description": "The order exists and is open.",
      "output": {
        "type": "object",
        "properties": {
          "platform": {
            "type": "string",
            "enum": [
              "web",
              "mobile",
              "store",
              "marketplace",
              "other"
            ]
          },
          "ship_country": {
            "type": "string",
            "pattern": "^[A-Z]{2}$",
            "description": "ISO 3166-1 alpha-2 destination country."
          },
          "items": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "properties": {
                "item_ref": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 200,
                  "description": "Reference to the order line in its source system."
                },
                "product_on_site_id": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 200,
                  "description": "Product id as the shop knows it."
                },
                "variant_text": {
                  "type": "string",
                  "maxLength": 500,
                  "description": "Variant string as the shop sent it."
                },
                "quantity": {
                  "type": "integer",
                  "minimum": 1
                }
              },
              "required": [
                "item_ref",
                "product_on_site_id",
                "variant_text",
                "quantity"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "platform",
          "ship_country",
          "items"
        ],
        "additionalProperties": false
      }
    },
    "missing": {
      "description": "The shop does not know the order.",
      "output": {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": false
      }
    },
    "cancelled": {
      "description": "The order was cancelled before shipping started.",
      "output": {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": false
      }
    }
  },
  "ledger": [
    "output.platform"
  ],
  "defaults": {
    "timeout": "60s",
    "retry": {
      "maxAttempts": 5,
      "initialInterval": "5s",
      "backoff": 2
    }
  }
}
